```python
def sort_third(l: list):
    l_sorted = sorted(l[i] for i in range(len(l)) if i % 3 == 0)
    l_new = []
    for i in range(len(l)):
      if i % 3 == 0:
        l_new.append(l_sorted.pop(0))
      else:
        l_new.append(l[i])
    return l_new  
```

