def pluck(arr):
    if not arr:
        return []
    min_even = float('inf')
    index = -1
    for i, val in enumerate(arr):
        if val % 2 == 0 and val < min_even:
            min_even = val
            index = i
    return [min_even, index] if index != -1 else [] 
```

