def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    count = 0
    for i in range(2, int(a**0.5) + 1):
        if is_prime(i) and a % i == 0:
            count += 1
            a //= i
    return count == 2 and is_prime(a) 
```

