def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    prime_factors = []
    for i in range(2, int(a**0.5) + 1):
        if a % i == 0:
            if is_prime(i):
                prime_factors.append(i)
            while a % i == 0:
                a //= i
    if a > 1 and is_prime(a):
        prime_factors.append(a)
    return len(prime_factors) == 3 
