def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    prime_factors = []
    i = 2
    while i * i <= a:
        if a % i:
            i += 1
        else:
            a //= i
            prime_factors.append(i)
    if a > 1:
        prime_factors.append(a)
    return len(prime_factors) == 3 and all(is_prime(p) for p in prime_factors) 
```

