def get_row(lst, x):
    res = []
    for i in range(len(lst)):
        for j in range(len(lst[i])):
            if lst[i][j] == x:
                res.append((i, j))
    res.sort(key=lambda x: x[0])
    for i in range(len(res)):
        for j in range(i+1, len(res)):
            if res[i][0] == res[j][0] and res[i][1] < res[j][1]:
                res[i], res[j] = res[j], res[i]
    return res 
```

