    for letter in message:
        if letter.isalpha():
            if letter in 'aeiouAEIOU':
                shifted_letter = chr((ord(letter) - ord('a' if letter.islower() else 'A') + 2) % 26 + ord('a' if letter.islower() else 'A'))
            else:
                shifted_letter = letter
            result.append(shifted_letter.swapcase())
        else:
            result.append(letter)
    return ''.join(result)   
