def skjkasdkd(lst):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    max_prime = 0
    for num in lst:
        if is_prime(num) and num > max_prime:
            max_prime = num
    sum_of_digits = 0
    while max_prime > 0:
        sum_of_digits += max_prime % 10
        max_prime //= 10
    return sum_of_digits 
```

