def max_fill(grid, capacity):
    import math
    total_fills = 0
    for col in range(len(grid[0])):
        current_fill = 0
        for row in range(len(grid)):
            if grid[row][col] == 1:
                current_fill += 1
        total_fills += math.ceil(current_fill / capacity)
    return total_fills 
```

