def max_fill(grid, capacity):
    rows = len(grid)
    cols = len(grid[0])
    bucket_fills = 0
    for row in range(rows):
        filled = 0
        for col in range(cols):
            if grid[row][col] == 1:
                filled += 1
                if filled == capacity:
                    bucket_fills += 1
                    filled = 0
        if filled:
            bucket_fills += 1
    return bucket_fills    
```

