def match_parens(lst):
    stack = []
    for paren in lst[0] + lst[1]:
        if paren == '(':
            stack.append(paren)
        elif paren == ')':
            if not stack:
                return 'No'
            stack.pop()
    return 'Yes' if not stack else 'No' 
```

