def get_odd_collatz(n):
    odds = []
    while n != 1:
        if n % 2 != 0:
            odds.append(n)
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
    if n == 1:
      odds.append(n)
    odds.sort()
    return odds 
