    min_path = None
    for start_row in range(N):
        for start_col in range(N):
            queue = [(start_row, start_col, [grid[start_row][start_col]], 1)]
            visited = set([(start_row, start_col)])
            while queue:
                row, col, path, length = queue.pop(0)
