def minPath(grid, k):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    min_path = float('inf')
    paths = []

    def dfs(row, col, path, visited_set):
        nonlocal min_path, paths
        visited_set.add((row, col))
        path.append(grid[row][col])
        if len(path) == k:
            if path < paths:
                paths = path.copy()
            return
        for r, c in [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]:
            if 0 <= r < rows and 0 <= c < cols and (r, c) not in visited_set:
                dfs(r, c, path, visited_set.copy())
        visited_set.remove((row, col))
        path.pop()

    for i in range(rows):
        for j in range(cols):
            dfs(i, j, [], set())

    return paths 
