def comb_sort(lst):
  n = len(lst)
  gap = n
  shrink = 1.3
  while gap > 1:
    gap = int(gap / shrink)
    for i in range(n - gap):
      if lst[i] > lst[i + gap]:
        lst[i], lst[i + gap] = lst[i + gap], lst[i]
  return lst 
```

```python
def comb_sort(arr):
  gap = len(arr)
  shrink = 1.3
  swapped = True
  while gap > 1 or swapped:
    gap = int(gap / shrink)
    if gap < 1:
      gap = 1
    swapped = False
    for i in range(len(arr) - gap):
      if arr[i] > arr[i + gap]:
        arr[i], arr[i + gap] = arr[i + gap], arr[i]
        swapped = True
  return arr 
```

