def amicable_numbers_sum(n):
  def sum_divisors(num):
    divisors = [1]
    for i in range(2, int(num**0.5) + 1):
      if num % i == 0:
        divisors.extend([i, num // i])
    return sum(divisors)
  sum = 0
  for i in range(1, n + 1):
    j = sum_divisors(i)
    if sum_divisors(j) == i and i != j:
      sum += i + j
  return sum 
```

