def find_length(s):
  max_diff = 0
  for i in range(len(s)):
    for j in range(i, len(s)):
      zeros = s[i:j+1].count('0')
      ones = s[i:j+1].count('1')
      max_diff = max(max_diff, abs(zeros - ones))
  return max_diff 
