def count_no_of_ways(n, k):
  if n == 1:
    return k
  if n == 2:
    return k * k
  dp = [[0 for _ in range(k)] for _ in range(n)]
  dp[0][0] = 1
  dp[1][0] = k
  for i in range(2, n):
    for j in range(k):
      dp[i][j] = (dp[i - 1][j] + dp[i - 2][j]) % 1000000007
      if i > 2:
        dp[i][j] += dp[i - 3][j]
  return sum(dp[n - 1]) % 1000000007 
```

