def max_Product(nums):
  if len(nums) < 2:
    return None
  max1 = nums[0]
  max2 = nums[1]
  if max2 > max1:
    max1, max2 = max2, max1
  for i in range(2, len(nums)):
    if nums[i] > max1:
      max2 = max1
      max1 = nums[i]
    elif nums[i] > max2:
      max2 = nums[i]
  return (max1, max2) 
