```python
def group_tuples(lst):
  result = []
  for i in range(len(lst)):
    common = lst[i][0]
    group = [lst[i]]
    for j in range(i + 1, len(lst)):
      if lst[j][0] == common:
        group.append(lst[j])
    result.append(tuple(element for sublist in group for element in sublist))
  return result 
```

```python
def group_tuples(lst):
  result = []
  groups = {}
  for tup in lst:
    first = tup[0]
    if first in groups:
      groups[first].append(tup[1])
    else:
      groups[first] = [tup[1]]
  for key, value in groups.items():
    result.append((key,) + tuple(value))
  return result 
```

