def group_tuples(tuple_list):
  grouped = []
  for i in range(len(tuple_list[0])):
    temp = []
    for tup in tuple_list:
      temp.append(tup[i])
    grouped.append(tuple(temp))
  return [tuple(group) for group in zip(*grouped)] 
```

